  1053
  1054        fdCount = 1;
  1055        if (is_CID ())
  1056        {
  1057          fdArray = &StructAtOffsetOrNull<CFF1FDArray> (cff, topDict.FDArrayOffset);
  1058          fdSelect = &StructAtOffsetOrNull<CFF1FDSelect> (cff, topDict.FDSelectOffset);
  1059          if (unlikely ((fdArray == &Null(CFF1FDArray)) || !fdArray->sanitize (&sc) ||
  1060              (fdSelect == &Null(CFF1FDSelect)) || !fdSelect->sanitize (&sc, fdArray->count)))
  1061          { fini (); return; }
  1062
  1063          fdCount = fdArray->count;
  1064        }
  1065        else
  1066        {
  1067          fdArray = &Null(CFF1FDArray);
  1068          fdSelect = &Null(CFF1FDSelect);
  1069        }
  1070
  1071        stringIndex = &StructAtOffset<CFF1StringIndex> (topDictIndex, topDictIndex->get_size ());
  1072        if ((stringIndex == &Null (CFF1StringIndex)) || !stringIndex->sanitize (&sc))
  1073        { fini (); return; }
