  1091
  1092        // parse CID font dicts and gather private dicts
  1093        if (is_CID ())
  1094        {
  1095          for (unsigned int i = 0; i < fdCount; i++)
  1096          {
  1097            ByteStr fontDictStr = (*fdArray)[i];
  1098            if (unlikely (!fontDictStr.sanitize (&sc))) { fini (); return; }
  1099            CFF1FontDictValues  *font;
  1100            CFF1FontDict_Interpreter font_interp;
  1101            font_interp.env.init (fontDictStr);
  1102            font = fontDicts.push ();
  1103            if (unlikely (font == &Crap(CFF1FontDictValues))) { fini (); return; }
  1104            font->init ();
  1105            if (unlikely (!font_interp.interpret (*font))) { fini (); return; }
  1106            PRIVDICTVAL  *priv = &privateDicts[i];
  1107            const ByteStr privDictStr (StructAtOffset<UnsizedByteStr> (cff, font->privateDictInfo.offset), font->privateDictInfo.size);
  1108            if (unlikely (!privDictStr.sanitize (&sc))) { fini (); return; }
  1109            DictInterpreter<PRIVOPSET, PRIVDICTVAL> priv_interp;
  1110            priv_interp.env.init (privDictStr);
  1111            priv->init ();
  1112            if (unlikely (!priv_interp.interpret (*priv))) { fini (); return; }
  1113
  1114            priv->localSubrs = &StructAtOffsetOrNull<CFF1Subrs> (privDictStr.str, priv->subrsOffset);
  1115            if (priv->localSubrs != &Null(CFF1Subrs) &&
  1116                unlikely (!priv->localSubrs->sanitize (&sc)))
  1117            { fini (); return; }
  1118          }
  1119        }
  1120        else  /* non-CID */
  1121        {
  1122          CFF1TopDictValues  *font = &topDict;
  1123          PRIVDICTVAL  *priv = &privateDicts[0];
  1124
  1125          const ByteStr privDictStr (StructAtOffset<UnsizedByteStr> (cff, font->privateDictInfo.offset), font->privateDictInfo.size);
  1126          if (unlikely (!privDictStr.sanitize (&sc))) { fini (); return; }
  1127          DictInterpreter<PRIVOPSET, PRIVDICTVAL> priv_interp;
  1128          priv_interp.env.init (privDictStr);
  1129          priv->init ();
  1130          if (unlikely (!priv_interp.interpret (*priv))) { fini (); return; }
  1131
  1132          priv->localSubrs = &StructAtOffsetOrNull<CFF1Subrs> (privDictStr.str, priv->subrsOffset);
  1133          if (priv->localSubrs != &Null(CFF1Subrs) &&
  1134              unlikely (!priv->localSubrs->sanitize (&sc)))
  1135          { fini (); return; }
  1136        }
  1137      }
